import itertools
from collections import defaultdict, deque

def find_shortest_cycle(adj, n, start, max_len=6):
    """Find shortest cycle through start vertex using BFS, up to max_len."""
    # BFS to find shortest cycle
    dist = {start: 0}
    parent = {start: -1}
    queue = deque([start])

    while queue:
        u = queue.popleft()
        if dist[u] >= max_len:
            continue
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                parent[v] = u
                queue.append(v)
            elif v != parent[u]:
                # Found a cycle
                cycle_len = dist[u] + dist[v] + 1
                return cycle_len
    return float('inf')

def check_girth(adj, n, min_girth=7):
    """Check if graph has girth at least min_girth."""
    max_cycle_to_check = min_girth - 1
    for start in range(n):
        cycle_len = find_shortest_cycle(adj, n, start, max_cycle_to_check)
        if cycle_len < min_girth:
            return False
    return True

def is_3_colorable(adj, n):
    """Check if graph is 3-colorable using backtracking."""
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for u in adj[v]:
                if u < v and colors[u] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def add_edge_and_check(adj, edges, u, v, n):
    """Try adding edge (u,v) and check if girth constraint is maintained."""
    # Check if adding (u,v) creates a short cycle
    # A cycle through (u,v) would have length = dist(u,v) + 1 in the current graph
    # We need dist(u,v) >= 6 to ensure cycle length >= 7

    # BFS from u to find distance to v
    dist = {u: 0}
    queue = deque([u])
    found_dist = float('inf')

    while queue:
        curr = queue.popleft()
        if dist[curr] >= 6:
            continue
        for neighbor in adj[curr]:
            if neighbor not in dist:
                dist[neighbor] = dist[curr] + 1
                queue.append(neighbor)
            elif neighbor == v:
                found_dist = min(found_dist, dist[curr] + 1)

    # If distance is < 6, adding edge creates cycle of length < 7
    if found_dist < 6:
        return False

    return True

